const PROMPT_FIELD_PATTERN = /(?:^|[_-])(?:prompt|instruction|description|caption|query|text)(?:$|[_-])/i;
const SHA256_HEX_PATTERN = /^[a-f0-9]{64}$/i;
const HASH64_HEX_PATTERN = /^[a-f0-9]{16}$/i;

class ProjectDatabaseSchemaTooNewError extends Error {
  constructor(foundVersion) {
    super(`项目数据库 schema ${foundVersion} 高于当前程序支持的 ${PROJECT_DATABASE_SCHEMA_VERSION}，已停止启动以防止降级写入`);
    this.name = 'ProjectDatabaseSchemaTooNewError';
    this.code = 'project_database_schema_too_new';
    this.status = 409;
    this.foundVersion = Number(foundVersion);
    this.supportedVersion = PROJECT_DATABASE_SCHEMA_VERSION;
  }
}

class ProjectDatabaseSchemaInvalidError extends Error {
  constructor(message, details = {}) {
    super(message);
    this.name = 'ProjectDatabaseSchemaInvalidError';
    this.code = 'project_database_schema_invalid';
    this.status = 500;
    this.details = details;
  }
}

class ProjectDatabaseRecoveryGenerationPathError extends ProjectDatabaseSchemaInvalidError {
  constructor(message, details = {}) {
    super(message, details);
    this.name = 'ProjectDatabaseRecoveryGenerationPathError';
    this.code = 'project_database_recovery_generation_path_invalid';
    this.status = 503;
  }
}

class ProjectDatabaseRecoveryGenerationUnavailableError extends ProjectDatabaseSchemaInvalidError {
  constructor(message, details = {}) {
    super(message, details);
    this.name = 'ProjectDatabaseRecoveryGenerationUnavailableError';
    this.code = 'project_database_recovery_generation_unavailable';
    this.status = 503;
  }
}

class ProjectDatabaseOwnerConflictError extends Error {
  constructor() {
    super('项目数据库正由另一个应用进程使用，已停止启动以避免并发写入');
    this.name = 'ProjectDatabaseOwnerConflictError';
    this.code = 'project_database_owner_conflict';
    this.status = 409;
    this.statusCode = 409;
  }
}

class ProjectDatabaseOwnerUnavailableError extends ProjectDatabaseSchemaInvalidError {
  constructor(message = '无法建立项目数据库进程所有权，已停止启动', details = {}) {
    super(message, details);
    this.name = 'ProjectDatabaseOwnerUnavailableError';
    this.code = 'project_database_owner_unavailable';
    this.status = 503;
    this.statusCode = 503;
  }
}

class ProjectDatabaseRecoveryError extends Error {
  constructor(message, details = {}, cause = null) {
    super(message, cause ? { cause } : undefined);
    this.name = 'ProjectDatabaseRecoveryError';
    this.code = 'project_database_recovery_failed';
    this.status = 503;
    this.details = details;
  }
}

function tokenizeProjectDatabaseSchemaSql(value) {
  const sql = String(value || '').trim();
  const tokens = [];
  for (let index = 0; index < sql.length;) {
    const character = sql[index];
    if (/\s/.test(character)) {
      index += 1;
      continue;
    }
    if (character === '-' && sql[index + 1] === '-') {
      index += 2;
      while (index < sql.length && sql[index] !== '\n' && sql[index] !== '\r') index += 1;
      continue;
    }
    if (character === '/' && sql[index + 1] === '*') {
      const end = sql.indexOf('*/', index + 2);
      index = end < 0 ? sql.length : end + 2;
      continue;
    }
    if (character === "'" || character === '"' || character === '`' || character === '[') {
      const closing = character === '[' ? ']' : character;
      let token = character;
      index += 1;
      while (index < sql.length) {
        token += sql[index];
        if (sql[index] === closing) {
          if (character !== '[' && sql[index + 1] === closing) {
            token += sql[index + 1];
            index += 2;
            continue;
          }
          index += 1;
          break;
        }
        index += 1;
      }
      tokens.push(token);
      continue;
    }
    if (/[A-Za-z0-9_.$]/.test(character)) {
      let end = index + 1;
      while (end < sql.length && /[A-Za-z0-9_.$]/.test(sql[end])) end += 1;
      tokens.push(sql.slice(index, end).toLowerCase());
      index = end;
      continue;
    }
    const operator = ['->>', '<=', '>=', '<>', '!=', '==', '||', '<<', '>>', '->']
      .find((candidate) => sql.startsWith(candidate, index));
    if (operator) {
      tokens.push(operator);
      index += operator.length;
      continue;
    }
    if (character !== ';' || sql.slice(index + 1).trim()) tokens.push(character);
    index += 1;
  }
  return tokens;
}

function normalizeProjectDatabaseSchemaSql(value) {
  if (value == null) return null;
  return tokenizeProjectDatabaseSchemaSql(value).join(' ');
}

function projectDatabaseSchemaDescriptorDigest(value) {
  return crypto.createHash('sha256').update(stableJson(value)).digest('hex');
}

function projectDatabaseSchemaSqlAfterKeyword(value, keywords) {
  const tokens = tokenizeProjectDatabaseSchemaSql(value);
  const candidates = Array.isArray(keywords) ? keywords : [keywords];
  for (let index = 0; index < tokens.length; index += 1) {
    const candidate = candidates.find((keyword) => {
      const parts = String(keyword).toLowerCase().split(/\s+/);
      return parts.every((part, offset) => tokens[index + offset] === part);
    });
    if (!candidate) continue;
    return tokens.slice(index).join(' ');
  }
  return tokens.join(' ');
}

function extractProjectDatabaseCheckConstraints(value) {
  const tokens = tokenizeProjectDatabaseSchemaSql(value);
  const checks = [];
  for (let index = 0; index < tokens.length - 1; index += 1) {
    if (tokens[index] !== 'check' || tokens[index + 1] !== '(') continue;
    let depth = 1;
    let cursor = index + 2;
    for (; cursor < tokens.length && depth > 0; cursor += 1) {
      if (tokens[cursor] === '(') depth += 1;
      if (tokens[cursor] === ')') depth -= 1;
    }
    if (depth !== 0) {
      checks.push(tokens.slice(index + 2).join(' '));
      break;
    }
    checks.push(tokens.slice(index + 2, cursor - 1).join(' '));
    index = cursor - 1;
  }
  return checks.sort();
}

function projectDatabaseSchemaTokensWithoutChecks(tokens) {
  const result = [];
  for (let index = 0; index < tokens.length;) {
    if (tokens[index] !== 'check' || tokens[index + 1] !== '(') {
      result.push(tokens[index]);
      index += 1;
      continue;
    }
    if (result.length >= 2 && result[result.length - 2] === 'constraint') {
      result.splice(result.length - 2, 2);
    }
    let depth = 1;
    index += 2;
    while (index < tokens.length && depth > 0) {
      if (tokens[index] === '(') depth += 1;
      if (tokens[index] === ')') depth -= 1;
      index += 1;
    }
  }
  return result;
}

function inspectProjectDatabaseTableDefinitionSemantics(database, tableName) {
  const table = database.prepare(`
    SELECT sql FROM sqlite_master
    WHERE type = 'table' AND name = ?
  `).get(tableName);
  const tokens = tokenizeProjectDatabaseSchemaSql(table?.sql);
  const definitionStart = tokens.indexOf('(');
  if (definitionStart < 0) return { columnDefinitions: [], tableConstraints: [], tableOptions: [] };

  const segments = [];
  let segment = [];
  let depth = 1;
  let definitionEnd = tokens.length;
  for (let index = definitionStart + 1; index < tokens.length; index += 1) {
    const token = tokens[index];
    if (token === '(') depth += 1;
    if (token === ')') {
      depth -= 1;
      if (depth === 0) {
        if (segment.length > 0) segments.push(segment);
        definitionEnd = index;
        break;
      }
    }
    if (token === ',' && depth === 1) {
      segments.push(segment);
      segment = [];
      continue;
    }
    segment.push(token);
  }

  const orderedColumnNames = database.pragma(`table_xinfo(${sqlitePragmaString(tableName)})`)
    .sort((left, right) => Number(left.cid) - Number(right.cid))
    .map((column) => String(column.name));
  const tableConstraintPrefixes = new Set(['constraint', 'primary', 'unique', 'check', 'foreign']);
  const columnDefinitions = [];
  const tableConstraints = [];
  let columnIndex = 0;
  for (const rawSegment of segments) {
    if (rawSegment.length === 0) continue;
    const isTableConstraint = tableConstraintPrefixes.has(rawSegment[0]);
    if (!isTableConstraint) {
      const name = orderedColumnNames[columnIndex] || String(rawSegment[0]);
      columnIndex += 1;
      columnDefinitions.push({
        name,
        definition: projectDatabaseSchemaTokensWithoutChecks(rawSegment.slice(1)).join(' '),
      });
      continue;
    }
    const definition = projectDatabaseSchemaTokensWithoutChecks(rawSegment);
    if (definition.length > 0) tableConstraints.push(definition.join(' '));
  }
  return {
    columnDefinitions: columnDefinitions.sort((left, right) => left.name.localeCompare(right.name)),
    tableConstraints: tableConstraints.sort(),
    tableOptions: tokens.slice(definitionEnd + 1),
  };
}

