function inspectProjectDatabaseConstraintTableStructure(database, tableName) {
  const flags = database.pragma('table_list').find((entry) => (
    String(entry.schema) === 'main' && String(entry.name) === tableName
  ));
  const columns = database.pragma(`table_xinfo(${sqlitePragmaString(tableName)})`)
    .map((column) => ({
      name: String(column.name),
      type: String(column.type || '').trim().toUpperCase(),
      notnull: Number(column.notnull) || 0,
      default: normalizeProjectDatabaseSchemaSql(column.dflt_value),
      primaryKey: Number(column.pk) || 0,
      hidden: Number(column.hidden) || 0,
    }))
    .sort((left, right) => left.name.localeCompare(right.name));
  const foreignKeyGroups = new Map();
  for (const foreignKey of database.pragma(`foreign_key_list(${sqlitePragmaString(tableName)})`)) {
    const key = Number(foreignKey.id) || 0;
    if (!foreignKeyGroups.has(key)) foreignKeyGroups.set(key, []);
    foreignKeyGroups.get(key).push(foreignKey);
  }
  const foreignKeys = [...foreignKeyGroups.values()].map((group) => {
    const ordered = group.sort((left, right) => Number(left.seq) - Number(right.seq));
    return {
      table: String(ordered[0]?.table || ''),
      onUpdate: String(ordered[0]?.on_update || '').toUpperCase(),
      onDelete: String(ordered[0]?.on_delete || '').toUpperCase(),
      match: String(ordered[0]?.match || '').toUpperCase(),
      columns: ordered.map((entry) => ({
        from: entry.from == null ? null : String(entry.from),
        to: entry.to == null ? null : String(entry.to),
      })),
    };
  }).sort((left, right) => stableJson(left).localeCompare(stableJson(right)));
  const constraintIndexes = database.pragma(`index_list(${sqlitePragmaString(tableName)})`)
    .filter((index) => String(index.origin) !== 'c')
    .map((index) => ({
      unique: Number(index.unique) || 0,
      origin: String(index.origin || ''),
      partial: Number(index.partial) || 0,
      columns: database.pragma(`index_xinfo(${sqlitePragmaString(String(index.name))})`)
        .filter((column) => Number(column.key) === 1)
        .sort((left, right) => Number(left.seqno) - Number(right.seqno))
        .map((column) => ({
          name: column.name == null ? null : String(column.name),
          cid: column.name == null ? Number(column.cid) : null,
          descending: Number(column.desc) || 0,
          collation: column.coll == null ? null : String(column.coll),
        })),
    }))
    .sort((left, right) => stableJson(left).localeCompare(stableJson(right)));
  const definitionSemantics = inspectProjectDatabaseTableDefinitionSemantics(database, tableName);
  return {
    kind: String(flags?.type || ''),
    withoutRowid: Number(flags?.wr) || 0,
    strict: Number(flags?.strict) || 0,
    columns,
    foreignKeys,
    constraintIndexes,
    ...definitionSemantics,
  };
}

function assertProjectDatabaseLegacyConstraintStructure(database, contract, actualColumnNames) {
  const canonical = new BetterSqlite3(':memory:');
  let expectedStructure;
  try {
    canonical.exec(contract.createReplacementSql);
    expectedStructure = inspectProjectDatabaseConstraintTableStructure(
      canonical,
      contract.replacementTableName,
    );
  } finally {
    canonical.close();
  }
  const actualColumnSet = new Set(actualColumnNames);
  expectedStructure.columns = expectedStructure.columns
    .filter((column) => actualColumnSet.has(column.name));
  expectedStructure.columnDefinitions = expectedStructure.columnDefinitions
    .filter((column) => actualColumnSet.has(column.name));
  const actualStructure = inspectProjectDatabaseConstraintTableStructure(
    database,
    contract.tableName,
  );
  if (stableJson(actualStructure) !== stableJson(expectedStructure)) {
    throw new ProjectDatabaseSchemaInvalidError('历史项目数据库约束表包含未知的非 CHECK 语义，已停止自动重建', {
      table: contract.tableName,
      expectedStructureDigest: projectDatabaseSchemaDescriptorDigest(expectedStructure),
      actualStructureDigest: projectDatabaseSchemaDescriptorDigest(actualStructure),
      expectedColumnCount: expectedStructure.columns.length,
      actualColumnCount: actualStructure.columns.length,
      expectedForeignKeyCount: expectedStructure.foreignKeys.length,
      actualForeignKeyCount: actualStructure.foreignKeys.length,
      expectedConstraintIndexCount: expectedStructure.constraintIndexes.length,
      actualConstraintIndexCount: actualStructure.constraintIndexes.length,
    });
  }
}

function inspectProjectDatabaseLegacyConstraintRebuild(database, contract) {
  const table = database.prepare(`
    SELECT sql FROM sqlite_master
    WHERE type = 'table' AND name = ?
  `).get(contract.tableName);
  if (!table) return false;
  if (!table.sql) {
    throw new ProjectDatabaseSchemaInvalidError('历史项目数据库约束表缺少可验证的建表定义', {
      table: contract.tableName,
    });
  }

  const expectedColumnNames = new Set(contract.columns);
  const actualColumnNames = database.pragma(`table_info(${sqlitePragmaString(contract.tableName)})`)
    .map((column) => String(column.name));
  const unexpectedColumns = actualColumnNames.filter((column) => !expectedColumnNames.has(column));
  const unsupportedMissingColumns = contract.columns.filter((column) => (
    !actualColumnNames.includes(column) && !contract.addableColumns.has(column)
  ));
  if (unexpectedColumns.length > 0 || unsupportedMissingColumns.length > 0) {
    throw new ProjectDatabaseSchemaInvalidError('历史项目数据库约束表列结构无法安全重建', {
      table: contract.tableName,
      expectedColumnCount: contract.columns.length,
      actualColumnCount: actualColumnNames.length,
      unexpectedColumnCount: unexpectedColumns.length,
      unsupportedMissingColumnCount: unsupportedMissingColumns.length,
      expectedColumnsDigest: projectDatabaseSchemaDescriptorDigest(contract.columns),
      actualColumnsDigest: projectDatabaseSchemaDescriptorDigest(actualColumnNames),
    });
  }
  assertProjectDatabaseLegacyConstraintStructure(database, contract, actualColumnNames);

  const expectedChecks = extractProjectDatabaseCheckConstraints(contract.createReplacementSql);
  const expectedCheckSet = new Set(expectedChecks);
  const actualChecks = extractProjectDatabaseCheckConstraints(table.sql);
  const unexpectedChecks = actualChecks.filter((check) => !expectedCheckSet.has(check));
  const hasDuplicateChecks = new Set(actualChecks).size !== actualChecks.length;
  if (unexpectedChecks.length > 0 || hasDuplicateChecks) {
    throw new ProjectDatabaseSchemaInvalidError('历史项目数据库约束表包含未知 CHECK 语义，已停止自动重建', {
      table: contract.tableName,
      expectedCheckCount: expectedChecks.length,
      actualCheckCount: actualChecks.length,
      unexpectedCheckCount: unexpectedChecks.length,
      hasDuplicateChecks,
      expectedChecksDigest: projectDatabaseSchemaDescriptorDigest(expectedChecks),
      actualChecksDigest: projectDatabaseSchemaDescriptorDigest(actualChecks),
    });
  }
  return expectedChecks.some((check) => !actualChecks.includes(check));
}

function assertProjectDatabaseLegacyConstraintObjects(database, contract) {
  const expectedObjects = new Map(contract.schemaObjects.map((entry) => [entry.name, entry]));
  const actualObjects = database.prepare(`
    SELECT type, name, sql FROM sqlite_master
    WHERE tbl_name = ? AND type IN ('index', 'trigger') AND sql IS NOT NULL
    ORDER BY type ASC, name ASC
  `).all(contract.tableName);
  const unexpectedObjects = actualObjects
    .filter((entry) => !expectedObjects.has(String(entry.name)))
    .map((entry) => ({ type: String(entry.type), name: String(entry.name) }));
  const missingObjects = contract.schemaObjects
    .filter((entry) => !actualObjects.some((actual) => String(actual.name) === entry.name))
    .map((entry) => ({ type: entry.type, name: entry.name }));
  const changedObjects = actualObjects.flatMap((entry) => {
    const expected = expectedObjects.get(String(entry.name));
    if (!expected) return [];
    const matches = String(entry.type) === expected.type
      && normalizeProjectDatabaseSchemaSql(entry.sql) === normalizeProjectDatabaseSchemaSql(expected.sql);
    return matches ? [] : [{ type: String(entry.type), name: String(entry.name) }];
  });
  // Missing canonical objects are repairable because the locked rebuild
  // recreates them from source-controlled SQL. Unknown or changed objects are
  // not repairable evidence and remain a hard failure.
  if (unexpectedObjects.length > 0 || changedObjects.length > 0) {
    throw new ProjectDatabaseSchemaInvalidError('历史项目数据库约束表的索引或触发器语义无法安全重建', {
      table: contract.tableName,
      expectedObjectCount: contract.schemaObjects.length,
      actualObjectCount: actualObjects.length,
      unexpectedObjectCount: unexpectedObjects.length,
      missingObjectCount: missingObjects.length,
      changedObjectCount: changedObjects.length,
      expectedObjectsDigest: projectDatabaseSchemaDescriptorDigest(contract.schemaObjects.map((entry) => ({
        type: entry.type,
        name: entry.name,
        definition: normalizeProjectDatabaseSchemaSql(entry.sql),
      }))),
      actualObjectsDigest: projectDatabaseSchemaDescriptorDigest(actualObjects.map((entry) => ({
        type: String(entry.type),
        name: String(entry.name),
        definition: normalizeProjectDatabaseSchemaSql(entry.sql),
      }))),
    });
  }
}

function rebuildProjectDatabaseLegacyConstraintTable(database, contract) {
  // This second inspection is deliberately adjacent to ALTER TABLE. The
  // caller holds an IMMEDIATE write transaction, so another connection cannot
  // add a column or change CHECK/index/trigger semantics between this gate and
  // the rebuild.
  const stillNeedsRebuild = inspectProjectDatabaseLegacyConstraintRebuild(database, contract);
  assertProjectDatabaseLegacyConstraintObjects(database, contract);
  // ensureColumn may itself complete the exact canonical CHECK contract for a
  // historical table whose only gap was an addable column. In that case there
  // is nothing to ALTER after the adjacent locked re-check.
  if (!stillNeedsRebuild) return false;
  const replacementExists = database.prepare(`
    SELECT 1 AS present FROM sqlite_master
    WHERE name = ?
    LIMIT 1
  `).get(contract.replacementTableName);
  if (replacementExists) {
    throw new ProjectDatabaseSchemaInvalidError('历史项目数据库约束表重建临时名已被占用', {
      table: contract.tableName,
      replacementTable: contract.replacementTableName,
    });
  }

  const columnList = contract.columns.map((column) => `"${column}"`).join(', ');
  const createCanonicalSql = contract.createReplacementSql.replace(
    contract.replacementTableName,
    contract.tableName,
  );
  database.exec(`
    ALTER TABLE "${contract.tableName}" RENAME TO "${contract.replacementTableName}";
    ${createCanonicalSql};
    INSERT INTO "${contract.tableName}"(${columnList})
      SELECT ${columnList} FROM "${contract.replacementTableName}";
    DROP TABLE "${contract.replacementTableName}";
    ${contract.schemaObjects.map((entry) => `${entry.sql};`).join('\n')}
  `);
  return true;
}

function sqlitePragmaString(value) {
  return `'${String(value).replace(/'/g, "''")}'`;
}

function sqliteSchemaIdentifier(value) {
  return `"${String(value).replace(/"/g, '""')}"`;
}

function projectDatabaseInvalidUuidSql(columnSql) {
  const lowered = `lower(${columnSql})`;
  const compact = `replace(${lowered}, '-', '')`;
  return `(
    typeof(${columnSql}) <> 'text'
    OR ${columnSql} <> ${lowered}
    OR length(${columnSql}) <> 36
    OR substr(${columnSql}, 9, 1) <> '-'
    OR substr(${columnSql}, 14, 1) <> '-'
    OR substr(${columnSql}, 19, 1) <> '-'
    OR substr(${columnSql}, 24, 1) <> '-'
    OR length(${compact}) <> 32
    OR ${compact} GLOB '*[^0-9a-f]*'
    OR substr(${lowered}, 15, 1) NOT GLOB '[1-8]'
    OR substr(${lowered}, 20, 1) NOT GLOB '[89ab]'
  )`;
}

function inspectProjectDatabaseStableIdentityViolations(database) {
  const violations = [];
  const tables = database.prepare(`
    SELECT name FROM sqlite_master
    WHERE type = 'table' AND name NOT LIKE 'sqlite_%'
    ORDER BY name ASC
  `).all();
  for (const table of tables) {
    const tableName = String(table.name);
    const identityColumns = database.pragma(`table_xinfo(${sqlitePragmaString(tableName)})`)
      .filter((column) => (
        String(column.name) === 'entity_uid'
        || String(column.name) === 'mutation_uid'
        || String(column.name).endsWith('_entity_uid')
      ));
    if (identityColumns.length === 0) continue;
    const projections = [];
    for (const [index, column] of identityColumns.entries()) {
      const columnName = String(column.name);
      const columnSql = sqliteSchemaIdentifier(columnName);
      const required = columnName === 'entity_uid'
        || columnName === 'mutation_uid'
        || Number(column.notnull) === 1;
      projections.push(
        `SUM(CASE WHEN ${required ? `${columnSql} IS NULL` : '0'} THEN 1 ELSE 0 END) AS missing_${index}`,
        `SUM(CASE WHEN ${columnSql} IS NOT NULL AND ${projectDatabaseInvalidUuidSql(columnSql)} THEN 1 ELSE 0 END) AS invalid_${index}`,
      );
    }
    const summary = database.prepare(`
      SELECT ${projections.join(', ')}
      FROM ${sqliteSchemaIdentifier(tableName)}
    `).get();
    for (const [index, column] of identityColumns.entries()) {
      const missingCount = Number(summary?.[`missing_${index}`] || 0);
      const invalidCount = Number(summary?.[`invalid_${index}`] || 0);
      if (missingCount === 0 && invalidCount === 0) continue;
      violations.push({
        table: tableName,
        column: String(column.name),
        missingCount,
        invalidCount,
      });
    }
  }
  const bindingContracts = [
    {
      table: 'asset_lineage',
      column: 'child_asset_id/child_asset_entity_uid',
      sql: `
        SELECT COUNT(*) AS count
        FROM asset_lineage lineage
        LEFT JOIN assets asset
          ON asset.id = lineage.child_asset_id
         AND asset.entity_uid = lineage.child_asset_entity_uid
        WHERE asset.id IS NULL
      `,
    },
    {
      table: 'asset_lineage',
      column: 'parent_asset_id/parent_asset_entity_uid',
      sql: `
        SELECT COUNT(*) AS count
        FROM asset_lineage lineage
        LEFT JOIN assets child
          ON child.id = lineage.child_asset_id
         AND child.entity_uid = lineage.child_asset_entity_uid
        LEFT JOIN assets asset
          ON asset.id = lineage.parent_asset_id
         AND asset.entity_uid = lineage.parent_asset_entity_uid
         AND asset.project_id = child.project_id
        WHERE child.id IS NULL OR asset.id IS NULL
      `,
    },
    {
      table: 'asset_lineage_events',
      column: 'asset_id/asset_entity_uid',
      sql: `
        SELECT COUNT(*) AS count
        FROM asset_lineage_events lineage
        LEFT JOIN assets asset
          ON asset.id = lineage.asset_id
         AND asset.project_id = lineage.project_id
         AND asset.entity_uid = lineage.asset_entity_uid
        LEFT JOIN asset_lineage_tombstones tombstone
          ON tombstone.id = lineage.asset_id
         AND tombstone.project_id = lineage.project_id
         AND tombstone.entity_uid = lineage.asset_entity_uid
        WHERE lineage.asset_entity_uid IS NOT NULL
          AND asset.id IS NULL
          AND tombstone.id IS NULL
      `,
    },
    {
      table: 'asset_lineage_events',
      column: 'parent_asset_id/parent_asset_entity_uid',
      sql: `
        SELECT COUNT(*) AS count
        FROM asset_lineage_events lineage
        LEFT JOIN assets asset
          ON asset.id = lineage.parent_asset_id
         AND asset.project_id = lineage.project_id
         AND asset.entity_uid = lineage.parent_asset_entity_uid
        LEFT JOIN asset_lineage_tombstones tombstone
          ON tombstone.id = lineage.parent_asset_id
         AND tombstone.project_id = lineage.project_id
         AND tombstone.entity_uid = lineage.parent_asset_entity_uid
        WHERE (lineage.parent_asset_id IS NULL AND lineage.parent_asset_entity_uid IS NOT NULL)
           OR (
             lineage.parent_asset_id IS NOT NULL
             AND lineage.parent_asset_entity_uid IS NOT NULL
             AND asset.id IS NULL
             AND tombstone.id IS NULL
           )
      `,
    },
    {
      table: 'collaboration_text_documents',
      column: 'target_id/target_entity_uid',
      sql: `
        SELECT COUNT(*) AS count
        FROM collaboration_text_documents document
        WHERE document.target_entity_uid IS NOT NULL
          AND (
            document.target_id IS NOT ('@t8/text-entity/' || lower(document.target_entity_uid))
            OR document.display_target_id IS NULL
            OR length(document.display_target_id) < 1
          )
      `,
    },
    {
      table: 'subflow_definitions',
      column: 'id/entity_uid/head',
      sql: `
        SELECT COUNT(*) AS count FROM (
          SELECT definition.project_id, definition.id, definition.version
          FROM subflow_definitions definition
          LEFT JOIN subflow_definition_heads head
            ON head.project_id = definition.project_id
           AND head.id = definition.id
          WHERE head.id IS NULL OR head.entity_uid IS NOT definition.entity_uid
          UNION ALL
          SELECT head.project_id, head.id, head.latest_version
          FROM subflow_definition_heads head
          LEFT JOIN subflow_definitions definition
            ON definition.project_id = head.project_id
           AND definition.id = head.id
           AND definition.version = head.latest_version
          WHERE definition.id IS NULL OR definition.entity_uid IS NOT head.entity_uid
        )
      `,
    },
    {
      table: 'review_comment_attachments',
      column: 'asset_id/asset_entity_uid',
      sql: `
        SELECT COUNT(*) AS count
        FROM review_comment_attachments attachment
        JOIN review_comments comment ON comment.id = attachment.comment_id
        JOIN review_threads thread ON thread.id = comment.thread_id
        LEFT JOIN assets asset
          ON asset.id = attachment.asset_id
         AND asset.entity_uid = attachment.asset_entity_uid
         AND asset.project_id = thread.project_id
        LEFT JOIN asset_lineage_tombstones tombstone
          ON tombstone.id = attachment.asset_id
         AND tombstone.entity_uid = attachment.asset_entity_uid
         AND tombstone.project_id = thread.project_id
        WHERE asset.id IS NULL AND tombstone.id IS NULL
      `,
    },
    {
      table: 'review_comment_attachments',
      column: 'asset_content_revision/content_hash',
      sql: `
        SELECT COUNT(*) AS count
        FROM review_comment_attachments attachment
        JOIN review_comments comment ON comment.id = attachment.comment_id
        JOIN review_threads thread ON thread.id = comment.thread_id
        JOIN assets asset
          ON asset.id = attachment.asset_id
         AND asset.entity_uid = attachment.asset_entity_uid
         AND asset.project_id = thread.project_id
        WHERE attachment.asset_content_revision > asset.content_revision
           OR (
             attachment.asset_content_revision = asset.content_revision
             AND attachment.content_hash IS NOT asset.content_hash
           )
      `,
    },
    {
      table: 'run_output_commits',
      column: 'display_ids/entity_uids',
      sql: `
        SELECT COUNT(*) AS count
        FROM run_output_commits output
        LEFT JOIN runs run
          ON run.id = output.run_id
         AND run.entity_uid = output.run_entity_uid
         AND run.project_id = output.project_id
         AND run.canvas_id = output.canvas_id
        LEFT JOIN node_runs node_run
          ON node_run.id = output.node_run_id
         AND node_run.entity_uid = output.node_run_entity_uid
         AND node_run.node_entity_uid = output.node_entity_uid
         AND node_run.run_id = output.run_id
        LEFT JOIN run_attempts attempt
          ON attempt.id = output.attempt_id
         AND attempt.entity_uid = output.attempt_entity_uid
         AND attempt.node_run_id = output.node_run_id
        LEFT JOIN assets asset
          ON asset.id = output.asset_id
         AND asset.entity_uid = output.asset_entity_uid
         AND asset.project_id = output.project_id
        LEFT JOIN asset_blobs blob
          ON blob.id = output.blob_id
         AND blob.entity_uid = output.blob_entity_uid
         AND blob.content_hash = output.content_hash
        LEFT JOIN run_events event
          ON event.entity_uid = output.event_entity_uid
         AND event.run_id = output.run_id
         AND event.node_run_id = output.node_run_id
        WHERE run.id IS NULL
           OR node_run.id IS NULL
           OR attempt.id IS NULL
           OR asset.id IS NULL
           OR blob.id IS NULL
           OR event.id IS NULL
      `,
    },
    {
      table: 'run_output_slot_reservations',
      column: 'asset_id/asset_entity_uid',
      sql: `
        SELECT COUNT(*) AS count
        FROM run_output_slot_reservations reservation
        LEFT JOIN assets asset
          ON asset.id = reservation.asset_id
         AND asset.entity_uid = reservation.asset_entity_uid
         AND asset.project_id = reservation.project_id
        LEFT JOIN asset_lineage_tombstones tombstone
          ON tombstone.id = reservation.asset_id
         AND tombstone.entity_uid = reservation.asset_entity_uid
         AND tombstone.project_id = reservation.project_id
        WHERE reservation.reservation_state = 'host-verified'
          AND asset.id IS NULL
          AND tombstone.id IS NULL
      `,
    },
  ];
  for (const contract of bindingContracts) {
    const invalidCount = Number(database.prepare(contract.sql).get()?.count || 0);
    if (invalidCount === 0) continue;
    violations.push({
      table: contract.table,
      column: contract.column,
      missingCount: 0,
      invalidCount,
    });
  }
  let invalidAssetBlobIdentityCount = 0;
  for (const row of database.prepare(`
    SELECT entity_uid, content_hash FROM asset_blobs
  `).iterate()) {
    const contentHash = normalizeSha256(row.content_hash);
    if (!contentHash || String(row.entity_uid || '') !== stableEntityUuid(
      't8-asset-blob-v1',
      'sha256',
      contentHash,
    )) {
      invalidAssetBlobIdentityCount += 1;
    }
  }
  if (invalidAssetBlobIdentityCount > 0) {
    violations.push({
      table: 'asset_blobs',
      column: 'content_hash/entity_uid',
      missingCount: 0,
      invalidCount: invalidAssetBlobIdentityCount,
    });
  }
  return violations;
}

function inspectProjectDatabaseTypedCanonicalViolations(database) {
  const counts = new Map();
  const mark = (table, column) => {
    const key = `${table}\u0000${column}`;
    const current = counts.get(key) || { table, column, invalidCount: 0 };
    current.invalidCount += 1;
    counts.set(key, current);
  };
  const parseRootObject = (serialized) => {
    const value = JSON.parse(String(serialized));
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
      throw new Error('typed JSON root must be an object');
    }
    return value;
  };
  const canonicalUuid = (value) => (
    typeof value === 'string'
    && value === value.toLowerCase()
    && isUuid(value)
  );
  const isKnownCanvasCatalogMetadataUpdatedAtDrift = (row, document) => {
    const rowUpdatedAt = Number(row.updated_at);
    const documentUpdatedAt = Number(document.updatedAt);
    return Number.isSafeInteger(rowUpdatedAt)
      && Number.isSafeInteger(documentUpdatedAt)
      && documentUpdatedAt >= 0
      && documentUpdatedAt < rowUpdatedAt
      && Object.prototype.hasOwnProperty.call(document, 'name')
      && typeof document.name === 'string'
      && document.name.length > 0
      && document.name.length <= 240
      && Object.prototype.hasOwnProperty.call(document, 'nodeCount')
      && Number.isSafeInteger(document.nodeCount)
      && document.nodeCount >= 0
      && Array.isArray(document.nodes)
      && document.nodeCount === document.nodes.length;
  };

  for (const row of database.prepare(`
    SELECT canvas_id, project_id, schema_version, revision, snapshot_json, updated_at
    FROM canvas_documents
  `).iterate()) {
    let document;
    try {
      document = parseRootObject(row.snapshot_json);
      // Validate the raw persisted value. Normalizing first would hide typed
      // identity damage and turn a current-schema read into silent repair.
      validateCanonicalProjectDocument(document);
      assertCanvasDocumentInvariants(document);
    } catch (_) {
      mark('canvas_documents', 'snapshot_json');
      continue;
    }
    if (typeof document.canvasId !== 'string' || document.canvasId !== String(row.canvas_id)) {
      mark('canvas_documents', 'snapshot_json.canvasId');
    }
    if (typeof document.projectId !== 'string' || document.projectId !== String(row.project_id)) {
      mark('canvas_documents', 'snapshot_json.projectId');
    }
    if (!Number.isSafeInteger(document.schemaVersion)
      || document.schemaVersion !== Number(row.schema_version)) {
      mark('canvas_documents', 'snapshot_json.schemaVersion');
    }
    if (!Number.isSafeInteger(document.revision) || document.revision !== Number(row.revision)) {
      mark('canvas_documents', 'snapshot_json.revision');
    }
    if ((!Number.isSafeInteger(document.updatedAt) || document.updatedAt !== Number(row.updated_at))
      // v2.9.2-v2.9.6 catalog-only rename writes advanced the SQL row
      // timestamp after persisting name/nodeCount but omitted the matching JSON
      // updatedAt. Accept only that exact legacy signature without mutating the
      // database during startup; getCanvas() already treats the row timestamp
      // as authoritative and the next real write persists canonical JSON.
      && !isKnownCanvasCatalogMetadataUpdatedAtDrift(row, document)) {
      mark('canvas_documents', 'snapshot_json.updatedAt');
    }
  }

  for (const row of database.prepare(`
    SELECT canvas_id, project_id, revision, snapshot_json
    FROM canvas_snapshots
  `).iterate()) {
    let document;
    try {
      document = parseRootObject(row.snapshot_json);
      validateCanonicalProjectDocument(document);
      assertCanvasDocumentInvariants(document);
    } catch (_) {
      mark('canvas_snapshots', 'snapshot_json');
      continue;
    }
    if (typeof document.canvasId !== 'string' || document.canvasId !== String(row.canvas_id)) {
      mark('canvas_snapshots', 'snapshot_json.canvasId');
    }
    if (typeof document.projectId !== 'string' || document.projectId !== String(row.project_id)) {
      mark('canvas_snapshots', 'snapshot_json.projectId');
    }
    if (!Number.isSafeInteger(document.revision) || document.revision !== Number(row.revision)) {
      mark('canvas_snapshots', 'snapshot_json.revision');
    }
  }

  for (const row of database.prepare(`
    SELECT id, entity_uid, version, project_id, name, definition_json, created_at
    FROM subflow_definitions
  `).iterate()) {
    let definition;
    try {
      definition = parseRootObject(row.definition_json);
    } catch (_) {
      mark('subflow_definitions', 'definition_json');
      continue;
    }
    let rootViolation = false;
    if (typeof definition.id !== 'string' || definition.id !== String(row.id)) {
      mark('subflow_definitions', 'definition_json.id');
      rootViolation = true;
    }
    if (typeof definition.projectId !== 'string' || definition.projectId !== String(row.project_id)) {
      mark('subflow_definitions', 'definition_json.projectId');
      rootViolation = true;
    }
    if (!Number.isSafeInteger(definition.version) || definition.version !== Number(row.version)) {
      mark('subflow_definitions', 'definition_json.version');
      rootViolation = true;
    }
    if (!canonicalUuid(definition.entityUid)
      || definition.entityUid !== String(row.entity_uid || '')) {
      mark('subflow_definitions', 'definition_json.entityUid');
      rootViolation = true;
    }
    if (!Number.isSafeInteger(definition.revision) || definition.revision < 1) {
      mark('subflow_definitions', 'definition_json.revision');
      rootViolation = true;
    }
    if (typeof definition.name !== 'string' || definition.name !== String(row.name)) {
      mark('subflow_definitions', 'definition_json.name');
      rootViolation = true;
    }
    if (!rootViolation) {
      try {
        const canonical = canonicalizeStoredSubflowDefinitionWithProjectIdentity(definition, row);
        if (stableJson(canonical) !== stableJson(definition)) {
          mark('subflow_definitions', 'definition_json');
        }
      } catch (_) {
        mark('subflow_definitions', 'definition_json');
      }
    }
  }

  return [...counts.values()].sort((left, right) => (
    left.table.localeCompare(right.table) || left.column.localeCompare(right.column)
  ));
}

function inspectProjectDatabaseCurrentSchemaManifest(database, options = {}) {
  const includedObjectNames = options.includedObjectNames == null
    ? null
    : new Set([...options.includedObjectNames].map(String));
  const excludedObjectNames = options.excludedObjectNames == null
    ? new Set()
    : new Set([...options.excludedObjectNames].map(String));
  const includesObject = (name) => (
    !excludedObjectNames.has(String(name))
    && (includedObjectNames == null || includedObjectNames.has(String(name)))
  );
  const objects = database.prepare(`
    SELECT type, name, tbl_name, sql
    FROM sqlite_master
    WHERE type IN ('table', 'index', 'trigger', 'view')
      AND name NOT LIKE 'sqlite_%'
    ORDER BY type ASC, name ASC
  `).all().filter((entry) => includesObject(entry.name));
  const tables = objects.filter((entry) => entry.type === 'table');
  const explicitIndexes = objects.filter((entry) => entry.type === 'index');
  const triggers = objects.filter((entry) => entry.type === 'trigger');
  const views = objects.filter((entry) => entry.type === 'view');
  const sqlByObjectName = new Map(objects.map((entry) => [String(entry.name), entry.sql]));
  const tableFlags = new Map(database.pragma('table_list')
    .filter((entry) => entry.schema === 'main' && !String(entry.name).startsWith('sqlite_'))
    .map((entry) => [String(entry.name), entry]));

  const tableDescriptors = tables.map((table) => {
    const tableName = String(table.name);
    const tableSql = table.sql == null ? null : String(table.sql);
    const flags = tableFlags.get(tableName) || {};
    const columns = database.pragma(`table_xinfo(${sqlitePragmaString(tableName)})`)
      .map((column) => ({
        cid: Number(column.cid),
        name: String(column.name),
        type: String(column.type || '').trim().toUpperCase(),
        notnull: Number(column.notnull) || 0,
        default: normalizeProjectDatabaseSchemaSql(column.dflt_value),
        primaryKey: Number(column.pk) || 0,
        hidden: Number(column.hidden) || 0,
      }))
      .sort((left, right) => left.cid - right.cid || left.name.localeCompare(right.name));

    const foreignKeyGroups = new Map();
    for (const foreignKey of database.pragma(`foreign_key_list(${sqlitePragmaString(tableName)})`)) {
      const key = Number(foreignKey.id) || 0;
      if (!foreignKeyGroups.has(key)) foreignKeyGroups.set(key, []);
      foreignKeyGroups.get(key).push(foreignKey);
    }
    const foreignKeys = [...foreignKeyGroups.values()].map((group) => {
      const ordered = group.sort((left, right) => Number(left.seq) - Number(right.seq));
      return {
        table: String(ordered[0]?.table || ''),
        onUpdate: String(ordered[0]?.on_update || '').toUpperCase(),
        onDelete: String(ordered[0]?.on_delete || '').toUpperCase(),
        match: String(ordered[0]?.match || '').toUpperCase(),
        columns: ordered.map((entry) => ({
          from: entry.from == null ? null : String(entry.from),
          to: entry.to == null ? null : String(entry.to),
        })),
      };
    }).sort((left, right) => stableJson(left).localeCompare(stableJson(right)));

    const indexes = database.pragma(`index_list(${sqlitePragmaString(tableName)})`)
      .filter((index) => String(index.origin) !== 'c' || includesObject(index.name))
      .map((index) => {
      const indexName = String(index.name);
      // key=0 rows describe storage/covering columns chosen by SQLite, not the
      // ordered key contract. Their order can change after an ADD COLUMN on a
      // WITHOUT ROWID table even when lookup, uniqueness, collation, and sort
      // semantics are unchanged.
      const columnsForIndex = database.pragma(`index_xinfo(${sqlitePragmaString(indexName)})`)
        .filter((column) => Number(column.key) === 1)
        .sort((left, right) => Number(left.seqno) - Number(right.seqno))
        .map((column) => ({
          name: column.name == null ? null : String(column.name),
          cid: column.name == null ? Number(column.cid) : null,
          descending: Number(column.desc) || 0,
          collation: column.coll == null ? null : String(column.coll),
          key: Number(column.key) || 0,
        }));
      const indexSql = sqlByObjectName.get(indexName);
      const indexTokens = tokenizeProjectDatabaseSchemaSql(indexSql);
      const whereIndex = indexTokens.indexOf('where');
      const firstParen = indexTokens.indexOf('(');
      const hasExpression = columnsForIndex.some((column) => column.cid === -2);
      return {
        name: String(index.origin) === 'c' ? indexName : null,
        unique: Number(index.unique) || 0,
        origin: String(index.origin || ''),
        partial: Number(index.partial) || 0,
        columns: columnsForIndex,
        expressionDefinition: hasExpression && firstParen >= 0
          ? indexTokens.slice(firstParen).join(' ')
          : null,
        where: whereIndex >= 0 ? indexTokens.slice(whereIndex + 1).join(' ') : null,
      };
      }).sort((left, right) => stableJson(left).localeCompare(stableJson(right)));

    const tableTokens = tokenizeProjectDatabaseSchemaSql(tableSql);
    const tableDefinitionStart = tableTokens.indexOf('(');
    return {
      name: tableName,
      kind: String(flags.type || 'table'),
      withoutRowid: Number(flags.wr) || 0,
      strict: Number(flags.strict) || 0,
      // Exclude only CREATE TABLE's identifier. The complete token stream from
      // the opening parenthesis preserves declared column order plus COLLATE,
      // ON CONFLICT, generated-column, table-FK/DEFERRABLE, and other SQLite
      // semantics that table_xinfo/foreign_key_list do not fully expose.
      definition: String(flags.type || '') !== 'virtual' && tableDefinitionStart >= 0
        ? tableTokens.slice(tableDefinitionStart).join(' ')
        : null,
      columns,
      foreignKeys,
      indexes,
      checks: extractProjectDatabaseCheckConstraints(tableSql),
      autoincrement: tableTokens.includes('autoincrement'),
      virtualDefinition: String(flags.type || '') === 'virtual'
        ? projectDatabaseSchemaSqlAfterKeyword(tableSql, 'using')
        : null,
    };
  }).sort((left, right) => left.name.localeCompare(right.name));

  const descriptor = {
    version: Number(options.descriptorVersion || PROJECT_DATABASE_SCHEMA_VERSION),
    counts: {
      tables: tables.length,
      indexes: explicitIndexes.length,
      triggers: triggers.length,
      views: views.length,
    },
    tables: tableDescriptors,
    triggers: triggers.map((trigger) => ({
      name: String(trigger.name),
      table: String(trigger.tbl_name),
      definition: projectDatabaseSchemaSqlAfterKeyword(trigger.sql, ['before', 'after', 'instead of']),
    })).sort((left, right) => left.name.localeCompare(right.name)),
    views: views.map((view) => ({
      name: String(view.name),
      definition: projectDatabaseSchemaSqlAfterKeyword(view.sql, 'as'),
    })).sort((left, right) => left.name.localeCompare(right.name)),
  };
  return {
    descriptor,
    counts: descriptor.counts,
    fingerprint: crypto.createHash('sha256').update(stableJson(descriptor)).digest('hex'),
  };
}

let projectDatabaseSchema32ExtensionManifestCache = null;

function freezeProjectDatabaseSchemaManifestValue(value) {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  Object.values(value).forEach(freezeProjectDatabaseSchemaManifestValue);
  return Object.freeze(value);
}

function projectDatabaseSchema32ExtensionManifest() {
  if (projectDatabaseSchema32ExtensionManifestCache) {
    return projectDatabaseSchema32ExtensionManifestCache;
  }
  const probe = new BetterSqlite3(':memory:');
  try {
    probe.pragma('foreign_keys = ON');
    probe.exec(PROJECT_DATABASE_MIGRATION_32_CREATE_SQL);
    probe.exec(PROJECT_DATABASE_MIGRATION_32_RUNTIME_GUARDS_SQL);
    const manifest = inspectProjectDatabaseCurrentSchemaManifest(probe, {
      descriptorVersion: PROJECT_DATABASE_MIGRATION_32.version,
      includedObjectNames: PROJECT_DATABASE_SCHEMA_32_OWNED_OBJECT_NAMES,
    });
    const actualObjectNames = probe.prepare(`
      SELECT name FROM sqlite_master
      WHERE type IN ('table', 'index', 'trigger', 'view')
        AND name NOT LIKE 'sqlite_%'
      ORDER BY name ASC
    `).all().map((row) => String(row.name)).sort();
    const expectedObjectNames = [...PROJECT_DATABASE_SCHEMA_32_OWNED_OBJECT_NAMES].sort();
    const quickCheck = probe.pragma('quick_check', { simple: true });
    const foreignKeyViolations = probe.pragma('foreign_key_check');
    if (manifest.fingerprint !== PROJECT_DATABASE_SCHEMA_32_EXTENSION_FINGERPRINT
      || stableJson(actualObjectNames) !== stableJson(expectedObjectNames)
      || quickCheck !== 'ok'
      || foreignKeyViolations.length !== 0) {
      throw new ProjectDatabaseSchemaInvalidError(
        'schema 32 内存 extension descriptor 与冻结契约不一致',
        {
          expectedFingerprint: PROJECT_DATABASE_SCHEMA_32_EXTENSION_FINGERPRINT,
          actualFingerprint: manifest.fingerprint,
          expectedObjectCount: expectedObjectNames.length,
          actualObjectCount: actualObjectNames.length,
          quickCheck,
          foreignKeyViolationCount: foreignKeyViolations.length,
        },
      );
    }
    projectDatabaseSchema32ExtensionManifestCache = freezeProjectDatabaseSchemaManifestValue(
      manifest,
    );
    return projectDatabaseSchema32ExtensionManifestCache;
  } finally {
    probe.close();
  }
}

function composeProjectDatabaseSchema32TargetManifestStrict(
  sourceManifest,
  extensionManifest,
  context,
) {
  try {
    return composeProjectDatabaseSchema32TargetManifest(sourceManifest, extensionManifest);
  } catch (error) {
    if (error instanceof ProjectDatabaseSchemaInvalidError) throw error;
    throw new ProjectDatabaseSchemaInvalidError(
      'schema 32 descriptor 分区无法合成精确目标 manifest',
      {
        context,
        compositionCode: error?.code || null,
        reason: String(error?.message || error),
        sourceFingerprint: sourceManifest?.fingerprint || null,
        extensionFingerprint: extensionManifest?.fingerprint || null,
      },
    );
  }
}

function projectDatabaseLogicalContentDigest(database) {
  const digest = crypto.createHash('sha256');
  const updateText = (value) => {
    const bytes = Buffer.from(String(value), 'utf8');
    const length = Buffer.allocUnsafe(8);
    length.writeBigUInt64BE(BigInt(bytes.length));
    digest.update(length);
    digest.update(bytes);
  };
  const updateValue = (value) => {
    if (value == null) {
      digest.update('n');
      return;
    }
    if (Buffer.isBuffer(value)) {
      digest.update('b');
      const length = Buffer.allocUnsafe(8);
      length.writeBigUInt64BE(BigInt(value.length));
      digest.update(length);
      digest.update(value);
      return;
    }
    if (typeof value === 'bigint') {
      digest.update('i');
      updateText(value.toString(10));
      return;
    }
    if (typeof value === 'number') {
      digest.update('r');
      const bytes = Buffer.allocUnsafe(8);
      bytes.writeDoubleBE(value);
      digest.update(bytes);
      return;
    }
    digest.update('t');
    updateText(value);
  };
  const tableTypes = new Map(database.pragma('table_list')
    .filter((entry) => entry.schema === 'main')
    .map((entry) => [String(entry.name), String(entry.type)]));
  const tables = database.prepare(`
    SELECT name FROM sqlite_master
    WHERE type = 'table'
      AND (name NOT LIKE 'sqlite_%' OR name = 'sqlite_sequence')
    ORDER BY name ASC
  `).all()
    .map((row) => String(row.name))
    .filter((name) => ['table', 'shadow'].includes(tableTypes.get(name) || 'table'));
  for (const tableName of tables) {
    const columns = database.pragma(`table_xinfo(${sqlitePragmaString(tableName)})`)
      .filter((column) => Number(column.hidden) !== 1)
      .sort((left, right) => Number(left.cid) - Number(right.cid));
    const columnNames = columns.map((column) => String(column.name));
    const primaryKeyColumns = columns
      .filter((column) => Number(column.pk) > 0)
      .sort((left, right) => Number(left.pk) - Number(right.pk))
      .map((column) => String(column.name));
    const ordering = primaryKeyColumns.length > 0 ? primaryKeyColumns : columnNames;
    updateText(tableName);
    updateText(columnNames.join('\u0000'));
    const selectColumns = columnNames.map(sqliteSchemaIdentifier).join(', ');
    const orderBy = ordering.length > 0
      ? ` ORDER BY ${ordering.map(sqliteSchemaIdentifier).join(', ')}`
      : '';
    const statement = database.prepare(
      `SELECT ${selectColumns} FROM ${sqliteSchemaIdentifier(tableName)}${orderBy}`,
    ).raw(true).safeIntegers(true);
    let rowCount = 0n;
    for (const row of statement.iterate()) {
      digest.update('[');
      row.forEach(updateValue);
      digest.update(']');
      rowCount += 1n;
    }
    updateText(rowCount.toString(10));
  }
  return digest.digest('hex');
}

function inspectProjectDatabaseHistoricalManifestMatch(database, manifest, options = {}) {
  const actual = inspectProjectDatabaseCurrentSchemaManifest(database, {
    descriptorVersion: manifest.version,
    excludedObjectNames: options.excludedObjectNames || [],
  });
  const expectedFingerprints = manifest.acceptedFingerprints
    .map((entry) => String(entry.fingerprint))
    .sort();
  const countsMatch = Object.keys(manifest.counts)
    .every((key) => actual.counts[key] === manifest.counts[key]);
  return {
    actual,
    expectedFingerprints,
    countsMatch,
    matched: countsMatch && expectedFingerprints.includes(actual.fingerprint),
  };
}

function assertProjectDatabaseHistoricalManifest(database, manifest, context, options = {}) {
  const match = inspectProjectDatabaseHistoricalManifestMatch(database, manifest, options);
  if (!match.matched) {
    throw new ProjectDatabaseSchemaInvalidError(
      `项目数据库 schema ${manifest.version} 结构指纹不匹配，已停止启动以避免伪造历史迁移`,
      {
        context,
        schemaVersion: manifest.version,
        expectedFingerprint: projectDatabaseSchemaDescriptorDigest(match.expectedFingerprints),
        expectedFingerprintCount: match.expectedFingerprints.length,
        actualFingerprint: match.actual.fingerprint,
        expectedCounts: manifest.counts,
        actualCounts: match.actual.counts,
      },
    );
  }
  return match.actual;
}

function findProjectDatabaseSchema23FingerprintMapping(fromFingerprint, toFingerprint) {
  return PROJECT_DATABASE_SCHEMA_23_FINGERPRINT_MAPPINGS.find((entry) => (
    entry.fromFingerprint === fromFingerprint && entry.toFingerprint === toFingerprint
  ));
}

function findProjectDatabaseSchema23To28FingerprintMapping(fromFingerprint, toFingerprint) {
  return PROJECT_DATABASE_SCHEMA_23_TO_28_FINGERPRINT_MAPPINGS.find((entry) => (
    entry.fromFingerprint === fromFingerprint && entry.toFingerprint === toFingerprint
  ));
}

function assertProjectDatabaseSchema22(database, context = 'schema-22') {
  return assertProjectDatabaseHistoricalManifest(
    database,
    PROJECT_DATABASE_SCHEMA_22_MANIFEST,
    context,
  );
}

function assertProjectDatabaseSchema23Base(database, context = 'schema-23') {
  return assertProjectDatabaseHistoricalManifest(
    database,
    PROJECT_DATABASE_SCHEMA_23_MANIFEST,
    context,
    { excludedObjectNames: PROJECT_DATABASE_SCHEMA_23_OWNED_OBJECT_NAMES },
  );
}

function assertProjectDatabaseHistoricalMigration23Receipt(database, context, options = {}) {
  const receiptObjects = database.prepare(`
    SELECT type, name FROM sqlite_master
    WHERE name = 'schema_historical_migration_receipts'
    ORDER BY type ASC, name ASC
  `).all();
  // Released v2.5.8 databases predate checksummed receipts. Their two strict
  // schema-23 fingerprints remain valid legacy endpoints without this table.
  if (receiptObjects.length === 0) return { present: false };
  if (receiptObjects.length !== 1
    || receiptObjects[0].type !== 'table'
    || receiptObjects[0].name !== 'schema_historical_migration_receipts') {
    throw new ProjectDatabaseSchemaInvalidError(
      '项目数据库 schema 23 历史 receipt 保留对象名称或类型不匹配',
      {
        context,
        actualObjectCount: receiptObjects.length,
        actualObjectsDigest: projectDatabaseSchemaDescriptorDigest(receiptObjects),
      },
    );
  }

  const extension = inspectProjectDatabaseCurrentSchemaManifest(database, {
    descriptorVersion: PROJECT_DATABASE_MIGRATION_23.version,
    includedObjectNames: PROJECT_DATABASE_SCHEMA_23_OWNED_OBJECT_NAMES,
  });
  const rows = database.prepare(`
    SELECT version, name, checksum, from_fingerprint, to_fingerprint,
           down_policy, applied_at
    FROM schema_historical_migration_receipts
    ORDER BY version ASC
  `).all();
  const receipt = rows.length === 1 ? rows[0] : null;
  const ledger = database.prepare(`
    SELECT version, applied_at FROM schema_migrations WHERE version = ?
  `).get(PROJECT_DATABASE_MIGRATION_23.version);
  const mapping = receipt && findProjectDatabaseSchema23FingerprintMapping(
    receipt.from_fingerprint,
    receipt.to_fingerprint,
  );
  const expectedToFingerprint = options.expectedToFingerprint || null;
  const expectedDownstreamFingerprint = options.expectedDownstreamFingerprint || null;
  const downstreamMapping = !expectedDownstreamFingerprint || (receipt
    && findProjectDatabaseSchema23To28FingerprintMapping(
      receipt.to_fingerprint,
      expectedDownstreamFingerprint,
    ));
  const exactReceipt = receipt
    && Number(receipt.version) === PROJECT_DATABASE_MIGRATION_23.version
    && receipt.name === PROJECT_DATABASE_MIGRATION_23.name
    && receipt.checksum === PROJECT_DATABASE_MIGRATION_23.checksum
    && (!expectedToFingerprint || receipt.to_fingerprint === expectedToFingerprint)
    && receipt.down_policy === PROJECT_DATABASE_MIGRATION_23.downPolicy
    && Number(receipt.applied_at) === Number(ledger?.applied_at);
  if (extension.fingerprint !== PROJECT_DATABASE_SCHEMA_23_RECEIPT_EXTENSION_FINGERPRINT
    || !mapping
    || !downstreamMapping
    || !exactReceipt) {
    throw new ProjectDatabaseSchemaInvalidError('项目数据库 schema 23 历史 migration receipt 不匹配', {
      context,
      expectedToFingerprint,
      expectedDownstreamFingerprint,
      extensionFingerprint: extension.fingerprint,
      expectedExtensionFingerprint: PROJECT_DATABASE_SCHEMA_23_RECEIPT_EXTENSION_FINGERPRINT,
      receiptCount: rows.length,
      receiptValid: Boolean(exactReceipt),
    });
  }
  return { present: true, receipt };
}

function assertProjectDatabaseSchema23(database, context = 'schema-23') {
  const base = assertProjectDatabaseSchema23Base(database, context);
  assertProjectDatabaseHistoricalMigration23Receipt(database, context, {
    expectedToFingerprint: base.fingerprint,
  });
  return base;
}

function assertProjectDatabaseSchema28(database, context = 'schema-28') {
  const actual = inspectProjectDatabaseCurrentSchemaManifest(database, {
    descriptorVersion: PROJECT_DATABASE_LEGACY_BRIDGE_VERSION,
    excludedObjectNames: [
      ...PROJECT_DATABASE_SCHEMA_23_OWNED_OBJECT_NAMES,
      ...PROJECT_DATABASE_SCHEMA_29_OWNED_OBJECT_NAMES,
      ...PROJECT_DATABASE_SCHEMA_30_OWNED_OBJECT_NAMES,
      ...PROJECT_DATABASE_SCHEMA_31_OWNED_OBJECT_NAMES,
      ...PROJECT_DATABASE_SCHEMA_32_OWNED_OBJECT_NAMES,
    ],
  });
  assertProjectDatabaseHistoricalMigration23Receipt(
    database,
    `${context}:historical-v23-receipt`,
    { expectedDownstreamFingerprint: actual.fingerprint },
  );
  const expected = PROJECT_DATABASE_SCHEMA_28_MANIFEST;
  const expectedFingerprints = expected.acceptedFingerprints
    .map((entry) => String(entry.fingerprint))
    .sort();
  const countsMatch = Object.keys(expected.counts)
    .every((key) => actual.counts[key] === expected.counts[key]);
  if (!countsMatch || !expectedFingerprints.includes(actual.fingerprint)) {
    throw new ProjectDatabaseSchemaInvalidError(
      '项目数据库当前 schema 结构指纹不匹配，已停止启动以避免静默修复',
      {
        context,
        schemaVersion: PROJECT_DATABASE_LEGACY_BRIDGE_VERSION,
        expectedFingerprint: projectDatabaseSchemaDescriptorDigest(expectedFingerprints),
        expectedFingerprintCount: expectedFingerprints.length,
        actualFingerprint: actual.fingerprint,
        expectedCounts: expected.counts,
        actualCounts: actual.counts,
      },
    );
  }
  const identityViolations = inspectProjectDatabaseStableIdentityViolations(database);
  if (identityViolations.length > 0) {
    throw new ProjectDatabaseSchemaInvalidError(
      '项目数据库稳定身份不变量校验失败，已停止启动以避免静默修复',
      { identityViolations },
    );
  }
  const typedCanonicalViolations = inspectProjectDatabaseTypedCanonicalViolations(database);
  if (typedCanonicalViolations.length > 0) {
    throw new ProjectDatabaseSchemaInvalidError(
      '项目数据库 typed canonical JSON 不变量校验失败，已停止启动以避免静默修复',
      { typedCanonicalViolations },
    );
  }
  return actual;
}

