      const now = Date.now();
      this.db.prepare('INSERT INTO schema_migrations(version, applied_at) VALUES (?, ?)')
        .run(PROJECT_DATABASE_MIGRATION_30.version, now);
      this._migration30Checkpoint('after-ledger');
